"""BFS shortest path in an unweighted graph."""

from collections import deque


def bfs_shortest_path(graph: dict[int, list[int]], start: int, end: int) -> list[int] | None:
    """Find the shortest path between start and end in an unweighted graph.

    Args:
        graph: Adjacency list mapping each node to its neighbors.
        start: Starting node.
        end: Target node.

    Returns:
        List of nodes on the shortest path (inclusive), or None if unreachable.
    """
    if start == end:
        return [start]

    visited = {start}
    queue = deque([(start, [start])])

    while queue:
        node, path = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor in visited:
                continue
            new_path = path + [neighbor]
            if neighbor == end:
                return new_path
            visited.add(neighbor)
            queue.append((neighbor, new_path))

    return None


# ---------- tests ----------

def test_direct_path():
    graph = {0: [1, 2], 1: [0, 3], 2: [0], 3: [1]}
    assert bfs_shortest_path(graph, 0, 3) == [0, 1, 3]


def test_start_equals_end():
    graph = {0: [1], 1: [0]}
    assert bfs_shortest_path(graph, 0, 0) == [0]


def test_no_path():
    graph = {0: [1], 1: [0], 2: [3], 3: [2]}
    assert bfs_shortest_path(graph, 0, 3) is None


def test_single_node():
    graph = {0: []}
    assert bfs_shortest_path(graph, 0, 0) == [0]


def test_multiple_shortest_paths():
    # 0-1-3 and 0-2-3 are both length 2; BFS should find one of them
    graph = {0: [1, 2], 1: [0, 3], 2: [0, 3], 3: [1, 2]}
    result = bfs_shortest_path(graph, 0, 3)
    assert result is not None
    assert result[0] == 0 and result[-1] == 3
    assert len(result) == 3


def test_longer_path():
    graph = {
        0: [1],
        1: [0, 2],
        2: [1, 3],
        3: [2, 4],
        4: [3],
    }
    assert bfs_shortest_path(graph, 0, 4) == [0, 1, 2, 3, 4]


def test_unreachable_node():
    graph = {0: [1], 1: [0], 2: []}
    assert bfs_shortest_path(graph, 0, 2) is None


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])

